307	namespace {
308	
309	// Palette colors resolved once per character and handed to every recipe.
310	struct RecipeColors {
311	    Color skin;
312	    Color hair;
313	    Color outfit;
314	    Color dark;
315	};
316	
317	// Rim color for the inverted-hull outline pass (issue #103) — near-black
318	// with a hint of blue so lines feel inked, not void.
319	constexpr Color kOutlineColor{32, 30, 38, 255};
320	
321	// The ONE place part ids map to shapes — the graphics-pack seam (issue
322	// #101). A content pack is exactly: catalog rows (PartDef/PartPalette
323	// with their `pack` tag) + recipe branches HERE. Nothing else — not the
324	// assembly, not the picker, not the render loop — changes when a pack is
325	// added. `at` is the part's anchor (bottom-center) and `dim` its declared
326	// size, both already in world units (contract scale applied); a part
327	// without a bespoke branch falls through to the generic declared-box
328	// recipe at the bottom, so new catalog rows always render.
329	void drawPartRecipe(const PartDef& part, const Vec3& at, const Vec3& dim,
330	                    const RecipeColors& c) {
331	    const float cy = at.y + dim.y * 0.5f;  // box center height
332	
333	    if (part.id == "body_round") {
334	        // Tapered trunk: narrow shoulders over a wider base.
335	        DrawCylinder({at.x, at.y, at.z}, dim.x * 0.34f, dim.x * 0.5f,
336	                     dim.y, 16, c.outfit);
337	    } else if (part.id == "head_round") {
338	        DrawSphere({at.x, cy, at.z}, dim.y * 0.5f, c.skin);
339	    } else if (part.id == "hair_tuft") {
340	        DrawSphere({at.x, at.y + dim.y * 0.3f, at.z}, dim.x * 0.5f, c.hair);
341	    } else if (part.id == "hair_bowl") {
342	        // Oversized cap sunk into the head reads as a bowl cut.
343	        DrawSphere({at.x, at.y - dim.y * 0.55f, at.z}, dim.x * 0.5f, c.hair);
344	    } else if (part.id == "hair_spikes") {
345	        for (int i = -1; i <= 1; ++i) {
346	            DrawCylinder({at.x + static_cast<float>(i) * dim.x * 0.30f,
347	                          at.y - dim.y * 0.25f, at.z},
348	                         0.f, dim.x * 0.16f, dim.y, 8, c.hair);
349	        }
350	    } else if (part.id == "body_slim") {
351	        // Slimmer tapered trunk than body_round (issue #92).
352	        DrawCylinder({at.x, at.y, at.z}, dim.x * 0.30f, dim.x * 0.42f,
353	                     dim.y, 16, c.outfit);
354	    } else if (part.id == "head_oval") {
355	        // Vertically stretched sphere reads as a longer, oval face.
356	        rlPushMatrix();
357	        rlTranslatef(at.x, cy, at.z);
358	        rlScalef(1.f, dim.y / dim.x, 1.f);
359	        DrawSphere({0.f, 0.f, 0.f}, dim.x * 0.5f, c.skin);
360	        rlPopMatrix();
361	    } else if (part.id == "hair_pony") {
362	        // A rounded cap plus a small tail behind the head.
363	        DrawSphere({at.x, at.y + dim.y * 0.30f, at.z}, dim.x * 0.5f, c.hair);
364	        DrawSphere({at.x, at.y - dim.y * 0.10f, at.z - dim.z * 0.5f},
365	                   dim.x * 0.34f, c.hair);
366	    } else if (part.id == "hair_mohawk") {
367	        // A single tall narrow crest running front-to-back.
368	        DrawCube({at.x, cy, at.z}, dim.x * 0.5f, dim.y, dim.z, c.hair);
369	    } else if (part.id == "hair_cap") {
370	        // A flat crown sunk onto the head plus a forward brim (+z is
371	        // the character's front, same as the eye sockets).
372	        DrawCylinder({at.x, at.y - dim.y * 0.40f, at.z}, dim.x * 0.50f,
373	                     dim.x * 0.55f, dim.y, 12, c.hair);
374	        DrawCube({at.x, at.y + dim.y * 0.10f, at.z + dim.z * 0.34f},
375	                 dim.x * 0.90f, dim.y * 0.18f, dim.z * 0.50f, c.hair);
376	    } else if (part.id == "hair_buzz") {
377	        // A tight crop: one thin disc hugging the scalp.
378	        DrawCylinder({at.x, at.y - dim.y * 0.30f, at.z}, dim.x * 0.48f,
379	                     dim.x * 0.50f, dim.y, 12, c.hair);
380	    } else if (part.id == "hair_bob") {
381	        // A sunken crown with side spheres reaching down over the ears.
382	        DrawSphere({at.x, at.y - dim.y * 0.35f, at.z}, dim.x * 0.50f, c.hair);
383	        DrawSphere({at.x - dim.x * 0.42f, at.y - dim.y * 1.10f, at.z},
384	                   dim.x * 0.22f, c.hair);
385	        DrawSphere({at.x + dim.x * 0.42f, at.y - dim.y * 1.10f, at.z},
386	                   dim.x * 0.22f, c.hair);
387	    } else if (part.id == "hair_curls") {
388	        // A cluster of small spheres: a lower row of three, two on top.
389	        for (int i = -1; i <= 1; ++i) {
390	            DrawSphere({at.x + static_cast<float>(i) * dim.x * 0.30f,
391	                        at.y + dim.y * 0.05f, at.z},
392	                       dim.x * 0.24f, c.hair);
393	        }
394	        DrawSphere({at.x - dim.x * 0.15f, at.y + dim.y * 0.45f, at.z},
395	                   dim.x * 0.22f, c.hair);
396	        DrawSphere({at.x + dim.x * 0.15f, at.y + dim.y * 0.45f, at.z},
397	                   dim.x * 0.22f, c.hair);
398	    } else if (part.id == "hair_bun") {
399	        // A rounded cap with a bun perched top-back.
400	        DrawSphere({at.x, at.y - dim.y * 0.25f, at.z}, dim.x * 0.52f, c.hair);
401	        DrawSphere({at.x, at.y + dim.y * 0.55f, at.z - dim.z * 0.35f},
402	                   dim.x * 0.30f, c.hair);
403	    } else if (part.id == "hair_side") {
404	        // A slab swept to one side, with a longer fall down that side.
405	        DrawCube({at.x - dim.x * 0.12f, cy, at.z}, dim.x * 0.76f, dim.y,
406	                 dim.z, c.hair);
407	        DrawCube({at.x - dim.x * 0.45f, at.y - dim.y * 0.60f, at.z},
408	                 dim.x * 0.20f, dim.y * 1.60f, dim.z * 0.80f, c.hair);
409	    } else if (part.id == "body_pear") {
410	        // Bottom-heavy rounded trunk — motherly Tomodachi silhouette.
411	        DrawCylinder({at.x, at.y, at.z}, dim.x * 0.28f, dim.x * 0.52f,
412	                     dim.y, 16, c.outfit);
413	    } else if (part.id == "hair_long") {
414	        // Crown plus a long fall down the back.
415	        DrawSphere({at.x, at.y - dim.y * 0.55f, at.z}, dim.x * 0.50f, c.hair);
416	        DrawCube({at.x, at.y - dim.y * 1.05f, at.z - dim.z * 0.42f},
417	                 dim.x * 0.82f, dim.y * 1.9f, dim.z * 0.22f, c.hair);
418	    } else if (part.id == "hair_afro") {
419	        // One big proud sphere.
420	        DrawSphere({at.x, at.y + dim.y * 0.20f, at.z}, dim.x * 0.52f, c.hair);
421	    } else if (part.id == "hair_braids") {
422	        // Crown with a stacked braid hanging at each side.
423	        DrawSphere({at.x, at.y - dim.y * 0.30f, at.z}, dim.x * 0.48f, c.hair);
424	        for (const float side : {-1.f, 1.f}) {
425	            DrawSphere({at.x + side * dim.x * 0.46f, at.y - dim.y * 0.95f, at.z},
426	                       dim.x * 0.15f, c.hair);
427	            DrawSphere({at.x + side * dim.x * 0.46f, at.y - dim.y * 1.35f, at.z},
428	                       dim.x * 0.12f, c.hair);
429	        }
430	    } else if (part.id == "hair_flat_top") {
431	        DrawCube({at.x, cy, at.z}, dim.x * 0.92f, dim.y, dim.z * 0.92f, c.hair);
432	    } else if (part.id == "hair_helmet") {
433	        // A shell sunk over the skull, open at the face.
434	        DrawCube({at.x, at.y - dim.y * 0.30f, at.z - dim.z * 0.06f},
435	                 dim.x, dim.y * 1.5f, dim.z * 0.88f, c.hair);
436	    } else if (part.id == "hair_wave") {
437	        // A slab with a lip swept up over the forehead.
438	        DrawCube({at.x, at.y - dim.y * 0.15f, at.z}, dim.x * 0.94f,
439	                 dim.y * 0.7f, dim.z * 0.94f, c.hair);
440	        DrawCube({at.x, at.y + dim.y * 0.45f, at.z + dim.z * 0.38f},
441	                 dim.x * 0.55f, dim.y * 0.8f, dim.z * 0.24f, c.hair);
442	    } else if (part.id == "eyes_sleepy") {
443	        // Two low flat lids.
444	        const float dx = dim.x * 0.5f - dim.y * 0.5f;
445	        DrawCube({at.x - dx, cy, at.z}, dim.y * 1.6f, dim.y * 0.45f, dim.z, c.dark);
446	        DrawCube({at.x + dx, cy, at.z}, dim.y * 1.6f, dim.y * 0.45f, dim.z, c.dark);
447	    } else if (part.id == "eyes_wink") {
448	        // One open pupil, one closed lid.
449	        const float dx = dim.x * 0.5f - dim.y * 0.5f;
450	        DrawSphere({at.x - dx, cy, at.z}, dim.y * 0.5f, c.dark);
451	        DrawCube({at.x + dx, cy, at.z}, dim.y * 1.5f, dim.y * 0.4f, dim.z, c.dark);
452	    } else if (part.id == "eyes_glasses") {
453	        // Two framed lenses joined by a bridge, pupils inside.
454	        const float dx = dim.x * 0.5f - dim.y * 0.55f;
455	        for (const float side : {-1.f, 1.f}) {
456	            DrawCube({at.x + side * dx, cy, at.z}, dim.y * 1.15f,
457	                     dim.y * 1.15f, dim.z * 0.6f, c.dark);
458	            DrawSphere({at.x + side * dx, cy, at.z + dim.z * 0.15f},
459	                       dim.y * 0.32f, c.skin);
460	        }
461	        DrawCube({at.x, cy + dim.y * 0.12f, at.z}, dx * 0.9f, dim.y * 0.18f,
462	                 dim.z * 0.5f, c.dark);
463	    } else if (part.id == "eyes_angry") {
464	        // Pupils under a heavy single brow bar.
465	        const float dx = dim.x * 0.5f - dim.y * 0.5f;
466	        DrawSphere({at.x - dx, cy - dim.y * 0.15f, at.z}, dim.y * 0.45f, c.dark);
467	        DrawSphere({at.x + dx, cy - dim.y * 0.15f, at.z}, dim.y * 0.45f, c.dark);
468	        DrawCube({at.x, cy + dim.y * 0.42f, at.z}, dim.x * 0.94f,
469	                 dim.y * 0.30f, dim.z, c.dark);
470	    } else if (part.id == "mouth_smile") {
471	        // A wide low bar with raised end dots reads as an upturned smile.
472	        DrawCube({at.x, cy - dim.y * 0.20f, at.z}, dim.x * 0.68f,
473	                 dim.y * 0.38f, dim.z, c.dark);
474	        DrawSphere({at.x - dim.x * 0.42f, cy + dim.y * 0.15f, at.z},
475	                   dim.y * 0.30f, c.dark);
476	        DrawSphere({at.x + dim.x * 0.42f, cy + dim.y * 0.15f, at.z},
477	                   dim.y * 0.30f, c.dark);
478	    } else if (part.id == "mouth_open" || part.id == "mouth_o") {
479	        // A flattened dark sphere: tall ellipse (open) or small ring (o).
480	        rlPushMatrix();
481	        rlTranslatef(at.x, cy, at.z);
482	        rlScalef(1.f, dim.y / dim.x, 0.35f);
483	        DrawSphere({0.f, 0.f, 0.f}, dim.x * 0.5f, c.dark);
484	        rlPopMatrix();
485	    } else if (part.id == "mouth_neutral") {
486	        DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, c.dark);
487	    } else if (part.category == PartCategory::Eyes) {
488	        if (part.id == "eyes_visor") {
489	            DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, c.dark);
490	        } else {
491	            // Two pupils split across the part's declared width.
492	            const float dx = dim.x * 0.5f - dim.y * 0.5f;
493	            DrawSphere({at.x - dx, cy, at.z}, dim.y * 0.5f, c.dark);
494	            DrawSphere({at.x + dx, cy, at.z}, dim.y * 0.5f, c.dark);
495	        }
496	    } else if (part.localSize.y > 0.f) {
497	        // Generic recipe: any part without a bespoke shape renders as
498	        // its declared box (skin for heads, hair on top, outfit below)
499	        // so NEW catalog parts appear immediately, just plainly.
500	        const Color color = part.category == PartCategory::Head ? c.skin
501	                            : part.category == PartCategory::Hair ? c.hair
502	                                                                  : c.outfit;
503	        DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, color);
504	    }
505	}
506	
507	}  // namespace
508	
509	void RaylibRenderer::drawCompositeCharacter(const CharacterLook& look,
510	                                            const Vec3& position, float facingDeg,
511	                                            bool walking, float phase, NpcFace face,
512	                                            bool dead) {
513	    const AssembledLook assembled = assembleLook(look);
514	    if (!assembled.ok) {
515	        // Invalid/stale look: the same marker cylinder the pack path uses.
516	        DrawCylinder({position.x, 0.f, position.z}, 0.35f, 0.35f, 1.8f, 12,
517	                     Color{200, 120, 80, 255});
518	        return;
519	    }
520	    // ONE uniform scale takes the whole assembly to the same height
521	    // contract pack characters use — parts were snapped in local space, so
522	    // proportions and socket alignment survive any future contract change.
523	    const float s = 1.8f / assembled.height;
524	
525	    const PartPalette* palette = &paletteCatalog().front();
526	    for (const PartPalette& candidate : paletteCatalog()) {
527	        if (candidate.id == look.paletteId) palette = &candidate;
528	    }
529	    const RecipeColors colors{
530	        Color{palette->skin[0], palette->skin[1], palette->skin[2], 255},
531	        Color{palette->hair[0], palette->hair[1], palette->hair[2], 255},
532	        Color{palette->outfit[0], palette->outfit[1], palette->outfit[2], 255},
533	        Color{38, 38, 44, 255}};
534	
535	    // Whole-figure transform: facing + procedural walk bob. Parts then draw
536	    // at their assembly-local positions and rotate correctly for free.
537	    // Death pose: the figure tips onto its back (a rigid tip-over, the
538	    // composite counterpart of the pack models' death clip), lifted a
539	    // little so the torso doesn't sink through the ground slab.
540	    const float bob = (walking && !dead) ? std::fabs(std::sin(phase * 7.f)) * 0.05f : 0.f;
541	    rlPushMatrix();
542	    rlTranslatef(position.x, position.y + bob + (dead ? 0.30f : 0.f), position.z);
543	    rlRotatef(facingDeg, 0.f, 1.f, 0.f);
544	    if (dead) rlRotatef(-90.f, 1.f, 0.f, 0.f);
545	
546	    // Cartoon outline, classic inverted hull (issue #103): every recipe is
547	    // issued TWICE — first inflated about its part's center, near-black,
548	    // with FRONT faces culled (so only a rim of the enlarged copy survives
549	    // around the real geometry), then normally. The passes are grouped —
550	    // not interleaved per part — because the cull-face switch must drain
551	    // the rlgl batch; two drains per character instead of two per part.
552	    constexpr float kHullScale = 1.06f;
553	    const RecipeColors outlineColors{kOutlineColor, kOutlineColor,
554	                                     kOutlineColor, kOutlineColor};
555	    rlDrawRenderBatchActive();
556	    rlSetCullFace(RL_CULL_FACE_FRONT);
557	    for (const PlacedPart& placed : assembled.parts) {
558	        const Vec3 at = placed.position * s;
559	        const Vec3 dim = placed.part->localSize * s;
560	        const float cy = at.y + dim.y * 0.5f;
561	        rlPushMatrix();  // inflate about the part's center, not the feet
562	        rlTranslatef(at.x, cy, at.z);
563	        rlScalef(kHullScale, kHullScale, kHullScale);
564	        rlTranslatef(-at.x, -cy, -at.z);
565	        drawPartRecipe(*placed.part, at, dim, outlineColors);
566	        rlPopMatrix();
567	    }
568	    rlDrawRenderBatchActive();
569	    rlSetCullFace(RL_CULL_FACE_BACK);
570	
571	    for (const PlacedPart& placed : assembled.parts) {
572	        // Anchor and size in world units — the contract scale is applied
573	        // HERE so recipes never see it.
574	        drawPartRecipe(*placed.part, placed.position * s,
575	                       placed.part->localSize * s, colors);
