170	bool lookIsValid(const CharacterLook& look, std::string* why) {
171	    const PartDef* chosen[kPartCategoryCount] = {};
172	    for (int c = 0; c < kPartCategoryCount; ++c) {
173	        const std::string& id = look.partIds[c];
174	        if (id.empty()) {
175	            if (why) *why = "missing part for a category";
176	            return false;
177	        }
178	        chosen[c] = findPart(id);
179	        if (!chosen[c]) {
180	            if (why) *why = "unknown part: " + id;
181	            return false;
182	        }
183	        if (chosen[c]->category != static_cast<PartCategory>(c)) {
184	            if (why) *why = id + " is in the wrong category slot";
185	            return false;
186	        }
187	    }
188	    for (int a = 0; a < kPartCategoryCount; ++a) {
189	        for (int b = a + 1; b < kPartCategoryCount; ++b) {
190	            if (!styleCompatible(*chosen[a], *chosen[b])) {
191	                if (why) {
192	                    *why = chosen[a]->id + " and " + chosen[b]->id +
193	                           " mix incompatible styles";
194	                }
195	                return false;
196	            }
197	        }
198	    }
199	    bool paletteKnown = false;
200	    for (const PartPalette& palette : paletteCatalog()) {
201	        paletteKnown = paletteKnown || palette.id == look.paletteId;
202	    }
203	    if (!paletteKnown) {
204	        if (why) *why = "unknown palette: " + look.paletteId;
205	        return false;
206	    }
207	    return true;
208	}
