210	AssembledLook assembleLook(const CharacterLook& look) {
211	    AssembledLook out;
212	    if (!lookIsValid(look, &out.error)) return out;
213	
214	    // Resolve category anchors in spec order (parents listed before
215	    // children), each child at parent anchor + parent's declared socket.
216	    Vec3 anchors[kPartCategoryCount];
217	    for (const CategorySpec& spec : categorySpecs()) {
218	        const int c = static_cast<int>(spec.category);
219	        const PartDef* part = findPart(look.partIds[c]);
220	        if (spec.socket[0] == '\0') {
221	            anchors[c] = Vec3{};  // root sits on the ground at the origin
222	        } else {
223	            const int p = static_cast<int>(spec.parent);
224	            const PartDef* parent = findPart(look.partIds[p]);
225	            const auto socket = parent->sockets.find(spec.socket);
226	            if (socket == parent->sockets.end()) {
227	                out.error = parent->id + " has no '" + spec.socket + "' socket";
228	                return out;
229	            }
230	            anchors[c] = anchors[p] + socket->second;
231	        }
232	        out.parts.push_back({part, anchors[c]});
233	        out.height = std::max(out.height, anchors[c].y + part->localSize.y);
234	    }
235	    out.ok = out.height > 0.f;
236	    if (!out.ok) out.error = "assembled look has no height";
237	    return out;
238	}
