240	CharacterLook randomizeLook(unsigned seed) {
241	    Rng rng{seed ? seed : 1u};  // xorshift can't start at 0
242	    CharacterLook look;
243	
244	    // Body first — it sets the style family the other picks must match.
245	    const auto bodies = partsForCategory(PartCategory::Body, "any");
246	    const PartDef* body = bodies[rng.pick(bodies.size())];
247	    look.part(PartCategory::Body) = body->id;
248	    for (const CategorySpec& spec : categorySpecs()) {
249	        if (spec.category == PartCategory::Body) continue;
250	        const auto options = partsForCategory(spec.category, body->styleTag);
251	        look.part(spec.category) = options[rng.pick(options.size())]->id;
252	    }
253	    const auto& palettes = paletteCatalog();
254	    look.paletteId = palettes[rng.pick(palettes.size())].id;
255	    return look;
256	}
