258	CharacterLook lookForPersona(const std::string& name,
259	                             const CharacterLook* authored,
260	                             std::string* whyFallback) {
261	    if (authored) {
262	        std::string why;
263	        if (lookIsValid(*authored, &why)) return *authored;
264	        if (whyFallback) *whyFallback = why;
265	    }
266	    // FNV-1a over the name: deterministic across runs and platforms, so an
267	    // unauthored persona keeps the same face forever instead of reshuffling
268	    // every launch.
269	    unsigned hash = 2166136261u;
270	    for (const char ch : name) {
271	        hash ^= static_cast<unsigned char>(ch);
272	        hash *= 16777619u;
273	    }
274	    return randomizeLook(hash);
275	}
