288	bool CharacterLook::fromJson(const std::string& json, CharacterLook& out) {
289	    const nlohmann::json j = nlohmann::json::parse(json, nullptr, false);
290	    if (!j.is_object()) return false;
291	    const char* keys[kPartCategoryCount] = {"body", "head", "eyes", "hair", "mouth"};
292	    for (int c = 0; c < kPartCategoryCount; ++c) {
293	        // Looks stored before the Mouth category (issue #104) have no
294	        // "mouth" key: default the canonical smile so the character keeps
295	        // its authored identity instead of demoting to the hash fallback.
296	        if (!j.contains(keys[c])) {
297	            if (static_cast<PartCategory>(c) == PartCategory::Mouth) {
298	                out.partIds[c] = "mouth_smile";
299	                continue;
300	            }
301	            return false;
302	        }
303	        if (!j[keys[c]].is_string()) return false;
304	        out.partIds[c] = j[keys[c]].get<std::string>();
